mapper.select:
SELECT event_id,
event_name,
event.bin_id,
bin.bin_name,
cluster.cluster_id,
cluster_name,
status,
`trigger`,
event_time
FROM event
JOIN bin ON event.bin_id = bin.bin_id
JOIN cluster ON bin.cluster_id = cluster.cluster_id
WHERE 1

    AND event.event_time BETWEEN #{startTime} AND #{endTime}


    AND bin.bin_id = #{binId}


    AND bin.cluster_id = #{clusterId}


    AND event.status = #{status}


    AND event.`trigger` = #{trigger}

ORDER BY event_time DESC LIMIT 50 ;
